`timescale 1ns/1ps
// Independent optimization benchmark driver and scoreboard. Baseline sources remain unchanged. Expected outputs are generated by the independent
// Python integer model; this testbench never calculates a DUT dot product.
module tb_rowpair_benchmark #(
    parameter integer RESULT_BUFFERS=2,
    parameter integer PIPE_MUL=1
);
    localparam integer LANES=8;
    localparam integer NX=6336, NW=16384, NB=256, NY=25344;
    logic clk=0, rst_n=0;
    always #5 clk=~clk;
    logic load_valid=0, load_ready;
    logic [1:0] load_kind=0;
    logic [13:0] load_addr=0;
    logic [39:0] load_data=0;
    logic start_valid=0, start_ready, busy, done, error;
    logic out_valid, out_ready=0, out_last;
    logic signed [47:0] out_data;
    logic [14:0] out_index;
    logic [31:0] core_cycles;
    kwt_linear_engine_rowpair #(.RESULT_BUFFERS(RESULT_BUFFERS), .PIPE_MUL(PIPE_MUL)) dut (.*);
    wire x0_read_enable=dut.x0_rd_en;
    wire x1_read_enable=dut.x1_rd_en;
    wire w_read_enable=dut.w_rd_en;
    wire b_read_enable=dut.b_rd_en;

    logic [15:0] x_mem [0:NX-1];
    logic [15:0] w_mem [0:NW-1];
    logic [39:0] b_mem [0:NB-1];
    logic [47:0] y_mem [0:NY-1];
    string vector_dir, filename, vcd_file;
    integer tasks=12, task_id, i, reset_interrupts=0, illegal_cases=0;
    integer total_outputs=0, completed=0, input_bubbles=0, stall_cycles=0;
    integer busy_load_rejections=0, stable_checks=0;
    integer full_window_cycles=0, cycle_counter=0, window_start;
    integer seed=20261015, random_stalls=1;
    integer task_load_start, task_load_cycles, task_stall_start;
    integer x_reads=0, w_reads=0, b_reads=0, load_words=0;
    integer expected_cycles, expected_b_reads;
    integer result_reads=0, result_writes=0, overlap_cycles=0, buffer_wait_cycles=0;
    bit measuring=0, dump_enabled=0;
    always @(posedge clk) begin
        if (measuring && rst_n) begin
            if (load_valid && load_ready) load_words=load_words+1;
            if (x0_read_enable) x_reads=x_reads+1;
            if (x1_read_enable) x_reads=x_reads+1;
            if (w_read_enable) w_reads=w_reads+LANES;
            if (b_read_enable) b_reads=b_reads+LANES;
            if (dut.result_rd_en) result_reads=result_reads+1;
            if (dut.result_wr_en) result_writes=result_writes+1;
            if (dut.compute_active && out_valid) overlap_cycles=overlap_cycles+1;
            if (dut.compute_wait_buffer) buffer_wait_cycles=buffer_wait_cycles+1;
        end
    end
    logic [31:0] random_state;
    always @(posedge clk) cycle_counter=cycle_counter+1;

    function automatic [31:0] next_random(input [31:0] state);
        reg [31:0] value;
        begin
            value=state^(state<<13);
            value=value^(value>>17);
            next_random=value^(value<<5);
        end
    endfunction

    task automatic reset_dut;
        begin
            @(negedge clk);
            rst_n=0; load_valid=0; start_valid=0; out_ready=0;
            #1;
            if (busy !== 0 || out_valid !== 0 || done !== 0 || error !== 0)
                $fatal(1,"reset did not clear externally visible state");
            repeat(3) @(negedge clk);
            rst_n=1;
            @(posedge clk); #1;
            if (busy !== 0 || out_valid !== 0 || done !== 0 || start_ready !== 0)
                $fatal(1,"reset left a runnable task or output");
        end
    endtask

    task automatic early_start;
        begin
            @(negedge clk); start_valid=1;
            repeat(3) begin
                @(posedge clk);
                if (start_ready !== 0) $fatal(1,"incomplete payload claimed start_ready");
                #1;
                if (busy !== 0 || out_valid !== 0 || done !== 0 || error !== 0)
                    $fatal(1,"early start changed execution/error state");
            end
            @(negedge clk); start_valid=0;
        end
    endtask

    task automatic send_word(input [1:0] kind, input integer address,
                             input [39:0] data_word, input bit bubbles);
        integer waits;
        begin
            @(negedge clk);
            random_state=next_random(random_state);
            if (bubbles && random_state[3:0]==0) begin
                load_valid=0;
                input_bubbles=input_bubbles+1;
                @(negedge clk);
            end
            load_valid=1; load_kind=kind; load_addr=14'(address); load_data=data_word;
            waits=0;
            while (load_ready !== 1 && waits<16) begin
                @(negedge clk); waits=waits+1;
            end
            if (load_ready !== 1) $fatal(1,"load handshake timeout kind=%0d addr=%0d",kind,address);
            @(posedge clk); #1;
            load_valid=0;
        end
    endtask

    task automatic load_task(input integer number);
        begin
            filename=$sformatf("%s/task_%02d_x.mem",vector_dir,number); $readmemh(filename,x_mem);
            filename=$sformatf("%s/task_%02d_w.mem",vector_dir,number); $readmemh(filename,w_mem);
            filename=$sformatf("%s/task_%02d_b.mem",vector_dir,number); $readmemh(filename,b_mem);
            filename=$sformatf("%s/task_%02d_y.mem",vector_dir,number); $readmemh(filename,y_mem);
            for (integer a=0;a<NX;a=a+1) send_word(0,a,{24'b0,x_mem[a]},random_stalls!=0);
            // Partial payload must not become runnable merely because X is loaded.
            early_start();
            for (integer a=0;a<NW;a=a+1) send_word(1,a,{24'b0,w_mem[a]},random_stalls!=0);
            for (integer a=0;a<NB;a=a+1) send_word(2,a,b_mem[a],random_stalls!=0);
            @(negedge clk); load_valid=0;
            if (error !== 0 || start_ready !== 1 || busy !== 0)
                $fatal(1,"fully loaded task not ready");
        end
    endtask

    task automatic begin_task;
        begin
            @(negedge clk); start_valid=1;
            @(posedge clk);
            if (start_ready !== 1) $fatal(1,"legal start was not accepted");
            #1;
            if (busy !== 1 || error !== 0) $fatal(1,"accepted start did not set busy");
            @(negedge clk); start_valid=0;
        end
    endtask

    task automatic collect_task(input integer number);
        integer received, clocks, task_stalls, stall_anchor;
        bit was_stalled, accepted_last, previous_accepted;
        logic [47:0] held_data;
        logic [14:0] held_index;
        logic held_last;
        begin
            received=0; clocks=0; task_stalls=0; stall_anchor=-1; was_stalled=0; previous_accepted=0;
            while (received<NY && clocks<1000000) begin
                @(negedge clk);
                random_state=next_random(random_state);
                out_ready=(random_stalls==0 || random_state[2:0]!=0);
                // Exercise long stalls, including final result and the 99th row.
                if (random_stalls!=0 && (received==0 || received==25088 || received==NY-1)) begin
                    if (stall_anchor!=received) begin stall_anchor=received; task_stalls=0; end
                    if (task_stalls < (received==0 ? 6000 : 5)) begin
                        out_ready=0;
                        if (out_valid) task_stalls=task_stalls+1;
                    end
                end
                load_valid=1; load_kind=3; load_addr=14'h3fff; load_data=40'hdeadbeef00;
                @(posedge clk);
                if (busy !== 1 || load_ready !== 0 || start_ready !== 0 || error !== 0)
                    $fatal(1,"busy load/start gating or error violated");
                busy_load_rejections=busy_load_rejections+1;
                if (random_stalls==0 && previous_accepted && received%512!=0 && out_valid!==1)
                    $fatal(1,"synchronous result stream contains an avoidable within-pair bubble at %0d",received);
                if (was_stalled) begin
                    if (out_valid !== 1 || out_data !== held_data || out_index !== held_index || out_last !== held_last)
                        $fatal(1,"output payload/valid changed under backpressure");
                    stable_checks=stable_checks+1;
                end
                was_stalled=(out_valid===1 && out_ready===0);
                if (random_stalls==0 && previous_accepted && received%512!=0 && out_valid!==1)
                    $fatal(1,"synchronous result stream contains an avoidable within-pair bubble at %0d",received);
                if (was_stalled) begin
                    held_data=out_data; held_index=out_index; held_last=out_last;
                    stall_cycles=stall_cycles+1;
                end
                accepted_last=0; previous_accepted=0;
                if (out_valid===1 && out_ready===1) begin
                    if (out_index !== 15'(received))
                        $fatal(1,"index mismatch task=%0d expected=%0d actual=%0d",number,received,out_index);
                    if (out_data !== y_mem[received])
                        $fatal(1,"value mismatch task=%0d index=%0d expected=%h actual=%h",number,received,y_mem[received],out_data);
                    if (out_last !== (received==NY-1))
                        $fatal(1,"last mismatch task=%0d index=%0d",number,received);
                    accepted_last=(received==NY-1); previous_accepted=1;
                    received=received+1; total_outputs=total_outputs+1;
                end else if (out_valid !== 0 && out_valid !== 1)
                    $fatal(1,"unknown output valid");
                #1;
                if (accepted_last) begin
                    if (done !== 1 || busy !== 0 || out_valid !== 0 || start_ready !== 0)
                        $fatal(1,"final handshake did not finish exactly once and invalidate task");
                end else if (done !== 0) $fatal(1,"premature completion");
                clocks=clocks+1;
            end
            if (received!=NY || clocks>=1000000 || (random_stalls!=0 && task_stalls==0))
                $fatal(1,"incomplete task or missing backpressure coverage");
            completed=completed+1;
            if (random_stalls==0 && core_cycles !== 32'(expected_cycles))
                $fatal(1,"no-stall cycle mismatch expected=%0d actual=%0d",expected_cycles,core_cycles);
            if (x_reads!=99*(256/LANES)*64 || w_reads!=50*256*64 ||
                b_reads!=expected_b_reads || load_words!=NX+NW+NB)
                $fatal(1,"memory/load conservation mismatch x=%0d w=%0d b=%0d load=%0d",x_reads,w_reads,b_reads,load_words);
            if (core_cycles < expected_cycles || core_cycles > expected_cycles+(stall_cycles-task_stall_start))
                $fatal(1,"cycle/stall accounting mismatch expected=%0d stalls=%0d observed=%0d",expected_cycles,stall_cycles-task_stall_start,core_cycles);
            if (result_reads!=NY || result_writes!=NY)
                $fatal(1,"result-buffer conservation mismatch reads=%0d writes=%0d",result_reads,result_writes);
            if (RESULT_BUFFERS==2 && overlap_cycles==0)
                $fatal(1,"double buffer never overlapped computation and output");
            if (random_stalls!=0 && buffer_wait_cycles==0)
                $fatal(1,"long backpressure never exhausted result buffers");
            $display("PASS ROWPAIR_BENCH_TASK task=%0d outputs=%0d core_cycles=%0d load_words=%0d load_cycles=%0d output_stalls=%0d x_reads=%0d w_reads=%0d b_reads=%0d window_cycles=%0d result_reads=%0d result_writes=%0d overlap_cycles=%0d buffer_wait_cycles=%0d",
                number,received,core_cycles,load_words,task_load_cycles,stall_cycles-task_stall_start,
                x_reads,w_reads,b_reads,cycle_counter-window_start,result_reads,result_writes,overlap_cycles,buffer_wait_cycles);
            measuring=0;
            if (dump_enabled && number==0) $dumpoff;
            @(negedge clk); load_valid=0; out_ready=1;
            repeat(4) begin
                @(posedge clk); #1;
                if (done !== 0 || out_valid !== 0 || busy !== 0 || start_ready !== 0 || error !== 0)
                    $fatal(1,"completion pulse repeated or stale task remained");
            end
            early_start();
        end
    endtask

    initial begin
        if (!$value$plusargs("VECTORS=%s",vector_dir)) $fatal(1,"missing VECTORS directory");
        if ($value$plusargs("TASKS=%d",tasks)) begin end
        if ($value$plusargs("SEED=%d",seed)) begin end
        if ($value$plusargs("RANDOM_STALLS=%d",random_stalls)) begin end
        if (random_stalls!=0 && random_stalls!=1) $fatal(1,"RANDOM_STALLS must be 0 or 1");
        if ($value$plusargs("VCD=%s",vcd_file)) begin
            $dumpfile(vcd_file); $dumpvars(1,dut); $dumpoff; dump_enabled=1;
        end
        expected_cycles=50*32*(66+PIPE_MUL) + (RESULT_BUFFERS==2 ? 49*17+8+258 : 49*531+8+258);
        expected_b_reads=50*256;
        if (tasks<2 || tasks>32) $fatal(1,"TASKS outside 2..32");
        random_state=32'(seed);
        if (random_state==0) random_state=1;
        reset_dut(); early_start();
        send_word(3,0,0,0);
        if (error !== 1) $fatal(1,"illegal kind accepted");
        repeat(3) begin
            @(posedge clk); #1;
            if (error !== 1 || load_ready !== 0 || start_ready !== 0 || busy !== 0)
                $fatal(1,"illegal-kind error not sticky");
        end
        illegal_cases=illegal_cases+1;
        reset_dut(); send_word(0,NX,0,0);
        if (error !== 1) $fatal(1,"out-of-range X address accepted");
        illegal_cases=illegal_cases+1;
        reset_dut(); send_word(0,0,1,0); early_start(); send_word(0,0,2,0);
        if (error !== 1) $fatal(1,"repeated/out-of-order address accepted");
        illegal_cases=illegal_cases+1;
        reset_dut();

        // Abort while synchronous memory/product pipelines contain in-flight work.
        load_task(0); begin_task();
        repeat(1) @(negedge clk);
        if (busy !== 1 || out_valid !== 0) $fatal(1,"pipeline reset setup invalid");
        reset_dut(); reset_interrupts=reset_interrupts+1; early_start();

        // Abort after the final memory issue, before the tail product commits.
        load_task(0); begin_task();
        repeat(64) @(negedge clk);
        if (busy !== 1 || out_valid !== 0) $fatal(1,"pipeline tail reset setup invalid");
        reset_dut(); reset_interrupts=reset_interrupts+1; early_start();

        // Abort an active task while its first computed result is backpressured.
        load_task(0); begin_task(); out_ready=0;
        i=0;
        while (out_valid !== 1 && i<10000) begin @(negedge clk); i=i+1; end
        if (out_valid !== 1) $fatal(1,"abort setup never produced output");
        repeat(5000) @(negedge clk);
        if (&dut.result_full !== 1'b1 || dut.compute_wait_buffer !== 1'b1)
            $fatal(1,"queued-result reset failed to fill every result buffer");
        reset_dut(); reset_interrupts=reset_interrupts+1; early_start();
        for (task_id=0;task_id<tasks;task_id=task_id+1) begin
            window_start=cycle_counter;
            x_reads=0; w_reads=0; b_reads=0; load_words=0;
            result_reads=0; result_writes=0; overlap_cycles=0; buffer_wait_cycles=0;
            task_stall_start=stall_cycles; measuring=1;
            task_load_start=cycle_counter;
            load_task(task_id);
            task_load_cycles=cycle_counter-task_load_start;
            if (dump_enabled && task_id==0) $dumpon;
            begin_task(); collect_task(task_id);
            full_window_cycles=full_window_cycles+(cycle_counter-window_start);
        end
        if (completed!=tasks || total_outputs!=tasks*NY || illegal_cases!=3 || reset_interrupts!=3 ||
            (random_stalls!=0 && (input_bubbles==0 || stall_cycles==0 || stable_checks==0)) || busy_load_rejections==0)
            $fatal(1,"coverage/conservation totals incomplete");
        $display("PASS ROWPAIR_BENCH_SUITE tasks=%0d outputs=%0d resets=%0d illegal=%0d input_bubbles=%0d stalls=%0d stable=%0d busy_load_rejections=%0d full_window_cycles=%0d",
                 completed,total_outputs,reset_interrupts,illegal_cases,input_bubbles,stall_cycles,stable_checks,busy_load_rejections,full_window_cycles);
        $finish;
    end
    initial begin #400000000; $fatal(1,"global watchdog"); end
endmodule
